"""Reanalyze immutable records generated by inner_transport --export-packets."""
from pathlib import Path
import argparse,json
import numpy as np
from .orbit_control import bound_critical


def analyze(filename):
    with np.load(filename,allow_pickle=False) as a:
        rec=a['records'];mass=float(a['packet_mass_msun']);tg=float(a['tg_myr'])
        match=float(a['matching_rg'])
    if rec.ndim!=2 or rec.shape[1]!=11 or not np.all(rec[:,10]==1):
        raise ValueError('Incomplete or unknown packet record schema')
    state=rec[:,3].astype(int)
    if not np.all(np.isin(state,[0,1,2])):raise ValueError('Unknown final state')
    duration=float(rec[:,4].max())
    ein=float(rec[:,1].sum()*mass);eout=float(rec[:,5].sum()*mass)
    late=(state==2)&(rec[:,4]>=duration/2)
    cohort=(rec[:,0]>=duration/2)&(rec[:,0]<duration*.8)
    co=rec[cohort];_,crit=bound_critical(co[:,1]);orig=co[:,2]<crit
    ret=rec[state==2];gam=ret[:,5]/np.sqrt(1-2/match);pt=ret[:,6]/match
    # Specific angular momentum is ell=r*u_t, not ell/r^2.
    pr2=gam**2-1-pt**2
    if len(ret) and pr2.min()<-1e-10:raise ArithmeticError('Invalid returned local state')
    return dict(file=Path(filename).name,packets=len(rec),tg_myr=tg,duration_myr=duration*tg,
        input_energy_flux_msun_myr=ein/(duration*tg),
        state_counts={str(i):int((state==i).sum()) for i in [0,1,2]},
        energy_ledger_relative=eout/ein-1,
        return_mean_specific_energy_gain=float(np.mean(rec[late,5]-rec[late,1])) if np.any(late) else None,
        return_min_local_radial_momentum_squared=float(pr2.min()) if len(pr2) else None,
        cohort=dict(packets=len(co),captured=int((co[:,3]==1).sum()),
            recruited=int(((~orig)&(co[:,3]==1)).sum()),
            initially_capturable_returned=int((orig&(co[:,3]==2)).sum()),
            censored=int((co[:,3]==0).sum())),
        scope='Prescribed-input inner response; residents right censored. No live long-term halo.')


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('packets',nargs='+',type=Path)
    ap.add_argument('--output-dir',default='outputs/audit',type=Path)
    a=ap.parse_args();a.output_dir.mkdir(parents=True,exist_ok=True)
    rows=[analyze(p) for p in a.packets]
    (a.output_dir/'packet_audit.json').write_text(json.dumps(rows,indent=2))
    print(json.dumps(rows,indent=2))

if __name__=='__main__':main()
